# -*- coding: utf-8 -*-
from odoo import models, fields, api

class AiAssistantPrompt(models.Model):
    _name = 'ai.assistant.prompt'
    _description = 'AI Smart Assistant'

    name = fields.Char(string="Prompt Title", required=True)
    prompt_type = fields.Selection([
        ('copywriting', 'Marketing Copywriting'),
        ('sql', 'SQL & Reporting Query'),
        ('email', 'Email Reply Drafter'),
        ('summary', 'Meeting & Document Summary'),
        ('general', 'General Intelligence')
    ], string="Assistant Mode", default="general", required=True)
    model_name = fields.Selection([
        ('gemini-1.5-pro', 'Google Gemini 1.5 Pro'),
        ('gemini-1.5-flash', 'Google Gemini 1.5 Flash'),
        ('claude-3-5-sonnet', 'Claude 3.5 Sonnet'),
        ('gpt-4o', 'GPT-4o Omnimodal')
    ], string="AI Model", default="gemini-1.5-flash", required=True)
    temperature = fields.Float(string="Creativity / Temperature", default=0.7)
    input_prompt = fields.Text(string="Input Prompt / Context", required=True)
    ai_response = fields.Text(string="Generated Response")
    state = fields.Selection([('draft', 'Draft'), ('completed', 'Completed')], string="Status", default="draft")
    user_id = fields.Many2one('res.users', string="User", default=lambda self: self.env.user)

    def action_generate(self):
        for rec in self:
            rec.ai_response = f"[AI Generated by {rec.model_name} for '{rec.name}']\n\nProcessed successfully. Content generated based on your prompt context:\n{rec.input_prompt}"
            rec.state = 'completed'

    def action_reset(self):
        for rec in self:
            rec.state = 'draft'

